    "answer": 0,
    "difficulty": "進階",
    "question": "\n<div class=\"reading-article\" style=\"background: var(--bg-secondary); padding: 1.5rem; border-radius: var(--radius-md); margin-bottom: 1.5rem; line-height: 1.6; border-left: 4px solid var(--color-primary);\">\n    <span class=\"en-assist\" data-tw=\"點擊朗讀文章\" data-en=\"Coffee is a brewed drink prepared from roasted coffee beans, the seeds of berries from certain Coffea species. When coffee berries turn from green to bright red in color – indicating ripeness – they are picked, processed, and dried. Dried coffee seeds are roasted to varying degrees, depending on the desired flavor. Roasted beans are ground and then brewed with near-boiling water to produce the beverage known as coffee.\" style=\"display: block;\">\n        Coffee is a brewed drink prepared from roasted coffee beans, the seeds of berries from certain Coffea species. When coffee berries turn from green to bright red in color – indicating ripeness – they are picked, processed, and dried. Dried coffee seeds are roasted to varying degrees, depending on the desired flavor. Roasted beans are ground and then brewed with near-boiling water to produce the beverage known as coffee. <span class=\"speak-icon\" style=\"cursor: pointer; float: right; font-size: 1.2rem;\" title=\"朗讀文章\">🔊</span>\n    </span>\n</div>\n<div class=\"question-prompt\" style=\"font-weight: 600; margin-bottom: 1rem;\">\n    <span class=\"en-assist\" data-tw=\"選出正確答案\">What is the main topic of this passage?<span class=\"speak-icon\">🔊</span></span>\n</div>",
    "explanation": "\n💡 <strong>題目與選項翻譯：</strong><br>題目：這篇文章的主題是什麼？<br><br>「The overview of the subject」：該主題的概述<br>「The future predictions」：對未來的預測<br>「A specific historical event」：一個特定的歷史事件<br>「Personal opinions of the author」：作者的個人觀點<br><br>💡 <strong>答案解析：</strong><br>\n文章主要在概述該主題的定義與背景。<br><br>\n💡 <strong>文章完整翻譯：</strong><br>\n咖啡是一種用烘焙過的咖啡豆（某些咖啡樹品種的漿果種子）沖泡的飲料。當咖啡漿果從綠色變成鮮紅色（表示成熟）時，它們就會被採摘、加工和乾燥。乾燥的咖啡種子會根據所需的風味被烘焙到不同程度。烘焙過的咖啡豆被研磨，然後用接近沸騰的水沖泡，製成被稱為咖啡的飲料。",
